// This builds a label correctly connected to its input (for === id)
function makeLabeledInput(id, labelText, type) {
  return '<label for="' + id + '">' + labelText + "</label>" +
    '<input type="' + type + '" id="' + id + '" name="' + id + '">';
}
console.log(makeLabeledInput("email", "Email address", "email"));

